mapper.select:
SELECT T.*, T.sys_sfc_category sysSfCategory FROM ( SELECT ss.*, (IF(ssi.user_id is null, 0, 1)) sysSfcInstall FROM sys_sfc ss LEFT JOIN sys_sfc_install ssi ON ssi.sys_sfc_id = ss.sys_sfc_id
AND ss.sys_sfc_id = #{condition.sysSfcId}
AND ss.sys_sfc_name LIKE CONCAT('%',#{condition.sysSfcName},'%')
AND ss.sys_sfc_function LIKE CONCAT('%',#{condition.sysSfcFunction},'%')
AND ss.sys_sfc_status = #{condition.sysSfcStatus}
AND ss.sys_sfc_desc LIKE CONCAT('%',#{condition.sysSfcDesc},'%')
AND ssi.user_id = #{userId}
) T ORDER BY sysSfcInstall DESC
